// Package codec provides shared little-endian binary encoding and decoding
// primitives used by the Go client library.
package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
	"runtime"
)

// Reader is a binary deserializer that reads sequentially from a byte slice
// using little-endian encoding. It accumulates errors silently; once an error
// is set, all subsequent reads return zero values without overwriting the
// error.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader that reads from the given payload.
func NewReader(payload []byte) *Reader {
	return &Reader{buf: payload}
}

// take reserves n bytes from the buffer and returns them. If the read would
// overrun the buffer, an error is recorded (annotated with the caller's file
// and line) and (nil, false) is returned. It is a no-op once an error is set.
func (r *Reader) take(n int) ([]byte, bool) {
	if r.err != nil {
		return nil, false
	}
	if n < 0 || r.pos+n > len(r.buf) {
		_, file, line, _ := runtime.Caller(2)
		r.err = fmt.Errorf("reader: need %d bytes at %s:%d, have %d", n, file, line, len(r.buf)-r.pos)
		return nil, false
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	return b, true
}

// U8 reads 1 byte as a uint8.
func (r *Reader) U8() uint8 {
	b, ok := r.take(1)
	if !ok {
		return 0
	}
	return b[0]
}

// U16 reads 2 bytes as a little-endian uint16.
func (r *Reader) U16() uint16 {
	b, ok := r.take(2)
	if !ok {
		return 0
	}
	return binary.LittleEndian.Uint16(b)
}

// U32 reads 4 bytes as a little-endian uint32.
func (r *Reader) U32() uint32 {
	b, ok := r.take(4)
	if !ok {
		return 0
	}
	return binary.LittleEndian.Uint32(b)
}

// U64 reads 8 bytes as a little-endian uint64.
func (r *Reader) U64() uint64 {
	b, ok := r.take(8)
	if !ok {
		return 0
	}
	return binary.LittleEndian.Uint64(b)
}

// F32 reads 4 bytes as an IEEE 754 little-endian float32.
func (r *Reader) F32() float32 {
	b, ok := r.take(4)
	if !ok {
		return 0
	}
	return math.Float32frombits(binary.LittleEndian.Uint32(b))
}

// Str reads exactly n bytes and returns them as a string.
func (r *Reader) Str(n int) string {
	b, ok := r.take(n)
	if !ok {
		return ""
	}
	return string(b)
}

// U32LenStr reads a 4-byte little-endian uint32 length prefix followed by that
// many bytes as a string.
func (r *Reader) U32LenStr() string {
	b, ok := r.take(4)
	if !ok {
		return ""
	}
	n := int(binary.LittleEndian.Uint32(b))
	s, ok := r.take(n)
	if !ok {
		return ""
	}
	return string(s)
}

// U8LenStr reads a 1-byte uint8 length prefix followed by that many bytes as a
// string.
func (r *Reader) U8LenStr() string {
	b, ok := r.take(1)
	if !ok {
		return ""
	}
	n := int(b[0])
	s, ok := r.take(n)
	if !ok {
		return ""
	}
	return string(s)
}

// Raw reads exactly n bytes and returns them as a []byte.
func (r *Reader) Raw(n int) []byte {
	b, ok := r.take(n)
	if !ok {
		return nil
	}
	return b
}

// Obj reads n bytes and passes them to v.UnmarshalBinary. If UnmarshalBinary
// returns an error, that error is stored in the Reader.
func (r *Reader) Obj(n int, v encoding.BinaryUnmarshaler) {
	b, ok := r.take(n)
	if !ok {
		return
	}
	if err := v.UnmarshalBinary(b); err != nil {
		r.err = err
	}
}

// Remaining returns the number of bytes not yet consumed.
func (r *Reader) Remaining() int {
	return len(r.buf) - r.pos
}

// Err returns the accumulated error, or nil if none occurred.
func (r *Reader) Err() error {
	return r.err
}
